use std::{fs,sync::Arc,collections::BTreeSet};use serde_json::{json,Value};use sha2::{Digest,Sha256};
mod model;
#[global_allocator]static ALLOC:zopro_core::alloc::Allocator=zopro_core::alloc::Allocator;
type Stamp=[u64;5];
fn earlier(a:Stamp,b:Stamp)->bool{if a[0]!=b[0]{return a[0]<b[0];}if a[1]!=b[1]{return false;}if a[2]!=b[2]{return a[2]<b[2];}a[3]==b[3]&&a[4]<b[4]}
fn main()->Result<(),Box<dyn std::error::Error>>{
 let args=std::env::args().collect::<Vec<_>>();if args.len()!=5{return Err("census IMAGE PRIOR_SOLVER OUT_JSON PRIVATE_STAMPS".into());}
 let file=fs::File::open(&args[1])?;let image=unsafe{memmap2::Mmap::map(&file)?};let prover=zopro_prover::Prover::load_image(Arc::new(image))?;
 let old=fs::read(&args[2])?;let serialized=prover.solver_image().ok_or("solver missing")?;assert_eq!(serialized,old,"actual image plan must match independent reader input");
 let (metadata,producer,edges,queries)=model::program(&old)?;let data=prover.parallel_readiness_census()?;assert!(data.len()>=15);assert_eq!(data[0],1);let n=data[1]as usize;let epochs=data[8]as usize;assert_eq!(data.len(),15+5*n);assert_eq!(data[2],metadata["wires"]);assert_eq!(data[3],metadata["stored_slots"]);assert_eq!(data[4],metadata["inputs"]);assert_eq!(data[5],metadata["constraints"]);assert_eq!(n,metadata["ops"].as_u64().unwrap()as usize);assert_eq!(data[6],queries[0].len()as u64);assert_eq!(data[7],queries[1].len()as u64);
 let stamps=data[15..].chunks_exact(5).map(|v|v.try_into().unwrap()).collect::<Vec<Stamp>>();let mut places=BTreeSet::new();for s in&stamps{assert!((s[0]as usize)<epochs);assert!(places.insert(*s));}
 for &(wire,reader)in&edges{let writer=producer[wire];if writer==0{continue;}if writer==reader{assert!(wire>=data[2]as usize);continue;}assert!(earlier(stamps[writer-1],stamps[reader-1]),"reader dependency is unordered or premature");}
 let mut reader_epoch=vec![None::<usize>;producer.len()];for &(wire,op)in&edges{let e=stamps[op-1][0]as usize;reader_epoch[wire]=Some(reader_epoch[wire].map_or(e,|old|old.max(e)));}
 let mut published=[queries[0].iter().map(|&w|producer[w]==0).collect::<Vec<_>>(),queries[1].iter().map(|&w|producer[w]==0).collect::<Vec<_>>()];let mut by_epoch=vec![Vec::new();epochs];for(w,&writer)in producer.iter().enumerate(){if writer!=0{by_epoch[stamps[writer-1][0]as usize].push(w);}}
 let mut outputs=serde_json::Map::new();let mut records=[Vec::new(),Vec::new()];for cut in 0..=epochs{
  if cut>0{for &w in&by_epoch[cut-1]{for q in 0..2{if let Ok(i)=queries[q].binary_search(&w){assert!(!published[q][i]);published[q][i]=true;}}}}
  let completed=stamps.iter().filter(|s|(s[0]as usize)<cut).count();
  for q in 0..2{let ready=queries[q].iter().map(|&w|producer[w]==0||(stamps[producer[w]-1][0]as usize)<cut).collect::<Vec<_>>();assert_eq!(ready,published[q]);let count=ready.iter().filter(|&&b|b).count();let prefix=ready.iter().take_while(|&&b|b).count();let chunks=ready.chunks(1024).filter(|c|c.iter().all(|&b|b)).count();let ready_chunk_points=ready.chunks(1024).filter(|c|c.iter().all(|&b|b)).map(|c|c.len()).sum::<usize>();let last=queries[q].iter().zip(&ready).filter(|&(w,&ready)|ready&&reader_epoch[*w].is_none_or(|e|e<cut)).count();records[q].push(json!({"epochs_completed":cut,"ops_completed":completed,"arbitrary_order_ready_points":count,"key_order_prefix_points":prefix,"complete_1024_chunks":chunks,"points_in_complete_chunks":ready_chunk_points,"past_final_solver_read_points":last}));}
 }
 let mut eligible=true;for q in 0..2{let before=records[q][epochs.saturating_sub(1)]["key_order_prefix_points"].as_u64().unwrap();let initial=records[q][0]["key_order_prefix_points"].as_u64().unwrap();eligible&=before>initial;outputs.insert(if q==0{"A"}else{"B"}.into(),json!({"points":queries[q].len(),"initial_input_ready_points":queries[q].iter().filter(|&&w|producer[w]==0).count(),"epoch_barriers":records[q],"ordered_stream_advances_before_last_epoch":before>initial}));}
 let bytes=data.iter().flat_map(|w|w.to_le_bytes()).collect::<Vec<_>>();fs::write(&args[4],&bytes)?;let out=json!({"complete":true,"actual_loaded_plan_matches_prior_serialized_image":true,"image_sha256":format!("{:x}",Sha256::digest(fs::read(&args[1])?)),"solver_sha256":format!("{:x}",Sha256::digest(&old)),"raw_schedule_sha256":format!("{:x}",Sha256::digest(&bytes)),"ops":n,"wires":data[2],"slots":data[3],"inputs":data[4],"constraints":data[5],"epochs":epochs,"root_tasks":data[9],"leaf_tasks":data[10],"tagged_leaf_tasks":data[11],"parallel":data[12]==1,"domain":data[13],"workspace_forecast_bytes":data[14],"query_results":Value::Object(outputs),"ordered_barrier_stream_structural_prerequisite":eligible,"all_op_slots_unique":true,"all_external_reads_ordered":true,"online_and_producer_counts_equal":true,"new_solver_executions":0,"new_proofs":0,"new_timing_samples":0,"workers":rayon::current_num_threads(),"serial_source_metadata":metadata,"limits":"outer-epoch barriers, not wall-time readiness; foldedK/H and grouping omitted; no permission to mutate Montgomery wires"});fs::write(&args[3],serde_json::to_vec_pretty(&out)?)?;println!("PARALLEL_READINESS ops={n} epochs={epochs} roots={} leaves={} ordered_prerequisite={eligible} no_solves_proofs_or_timings",data[9],data[10]);Ok(())
}
